// Recovery Tracker v2 — dynamic substance tracking
const STORAGE_KEY = 'recovery-tracker-v2';
const STORAGE_KEY_V1 = 'use-tracker-v1';
const LAST_SAVED_KEY = 'recovery-tracker-v2-last-saved';
const AUTO_BACKUP_KEY = 'recovery-tracker-v2-auto-backup';
const CHANGE_HISTORY_KEY = 'recovery-tracker-v2-change-history';
const DASHBOARD_LAYOUT_KEY = 'recovery-tracker-v2-dashboard-layout';
const MAX_CHANGE_HISTORY = 40;
const DASHBOARD_ALL = 'all';
const THEME_PREFERENCE_KEY = 'recoveryTracker.themePreference';
const APPEARANCE_VIEW_MODES = Object.freeze(['auto', 'phone', 'laptop']);
const APPEARANCE_VIEW_MODE_LAPTOP_MQ = '(min-width: 768px)';
const COLUMN_PRESET_IDS = Object.freeze(['basic', 'cost', 'inventory', 'detailed']);
const DEFAULT_DASHBOARD_WIDGETS = Object.freeze([
    'todayUsed', 'weekUsed', 'monthUsed', 'spentMonth', 'monthCap', 'streak', 'quickActions'
]);

let themePreference = 'dark';
let resolvedTheme = 'dark';
let themeMediaQuery = null;
let appearanceViewModeMediaQuery = null;

function getSystemTheme() {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

function resolveTheme(preference = themePreference) {
    if (preference === 'light') return 'light';
    if (preference === 'system') return getSystemTheme();
    return 'dark';
}

function applyResolvedTheme(theme) {
    resolvedTheme = theme;
    document.documentElement.dataset.theme = theme;
    updateThemePreviewUI();
}

function loadThemePreference() {
    try {
        const saved = localStorage.getItem(THEME_PREFERENCE_KEY);
        if (saved === 'dark' || saved === 'light' || saved === 'system') {
            themePreference = saved;
        }
    } catch (_) { /* ignore */ }
    applyResolvedTheme(resolveTheme(themePreference));
}

function onSystemThemeChange() {
    if (themePreference === 'system') {
        applyResolvedTheme(resolveTheme('system'));
    }
}

function setupThemeSystemListener() {
    if (themeMediaQuery) {
        themeMediaQuery.removeEventListener('change', onSystemThemeChange);
        themeMediaQuery = null;
    }
    if (themePreference === 'system') {
        themeMediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
        themeMediaQuery.addEventListener('change', onSystemThemeChange);
    }
}

function updateThemePreviewUI() {
    const select = document.getElementById('theme-preference');
    if (select && select.value !== themePreference) {
        select.value = themePreference;
    }
    const preview = document.getElementById('theme-preview-text');
    const systemNote = document.getElementById('theme-system-note');
    if (!preview) return;

    const resolvedLabel = resolvedTheme.charAt(0).toUpperCase() + resolvedTheme.slice(1);
    if (themePreference === 'system') {
        const prefLabel = 'System';
        preview.textContent = `Current theme: ${prefLabel} → ${resolvedLabel}`;
        if (systemNote) {
            systemNote.textContent = `Using system setting: ${resolvedLabel}`;
            systemNote.classList.remove('hidden');
        }
    } else {
        const prefLabel = themePreference.charAt(0).toUpperCase() + themePreference.slice(1);
        preview.textContent = `Current theme: ${prefLabel}`;
        systemNote?.classList.add('hidden');
    }
}

function setThemePreference(preference) {
    if (preference !== 'dark' && preference !== 'light' && preference !== 'system') return;
    themePreference = preference;
    try {
        localStorage.setItem(THEME_PREFERENCE_KEY, preference);
    } catch (_) { /* ignore */ }
    applyResolvedTheme(resolveTheme(preference));
    setupThemeSystemListener();
}

function initTheme() {
    loadThemePreference();
    setupThemeSystemListener();
    updateThemePreviewUI();
}

function normalizeAppearanceViewMode(value) {
    return APPEARANCE_VIEW_MODES.includes(value) ? value : 'auto';
}

function getAppearanceViewMode(data = appData) {
    return normalizeAppearanceViewMode(data?.settings?.appearanceViewMode);
}

function resolveAppearanceViewLayout(mode = getAppearanceViewMode()) {
    const preference = normalizeAppearanceViewMode(mode);
    if (preference === 'phone') return 'phone';
    if (preference === 'laptop') return 'laptop';
    try {
        if (typeof window !== 'undefined' && window.matchMedia?.(APPEARANCE_VIEW_MODE_LAPTOP_MQ)?.matches) {
            return 'laptop';
        }
    } catch (_) { /* ignore */ }
    return 'phone';
}

function isAppearancePhoneLayout() {
    return document.documentElement?.dataset?.viewLayout !== 'laptop';
}

function isAppearanceLaptopLayout() {
    return document.documentElement?.dataset?.viewLayout === 'laptop';
}

function syncAppearanceViewModeUI(mode = getAppearanceViewMode()) {
    const preference = normalizeAppearanceViewMode(mode);
    const select = document.getElementById('appearance-view-mode');
    if (select && select.value !== preference) select.value = preference;
    document.querySelectorAll('[data-appearance-view-mode]').forEach((btn) => {
        const active = btn.getAttribute('data-appearance-view-mode') === preference;
        btn.classList.toggle('active', active);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
}

function applyAppearanceViewMode(mode = getAppearanceViewMode()) {
    const preference = normalizeAppearanceViewMode(mode);
    const layout = resolveAppearanceViewLayout(preference);
    const root = document.documentElement;
    if (root) {
        root.dataset.viewMode = preference;
        root.dataset.viewLayout = layout;
    }
    syncAppearanceViewModeUI(preference);
    return layout;
}

function setupAppearanceViewModeListener() {
    if (appearanceViewModeMediaQuery) {
        appearanceViewModeMediaQuery.removeEventListener('change', onAppearanceViewModeViewportChange);
        appearanceViewModeMediaQuery = null;
    }
    if (getAppearanceViewMode() !== 'auto') return;
    if (typeof window === 'undefined' || !window.matchMedia) return;
    appearanceViewModeMediaQuery = window.matchMedia(APPEARANCE_VIEW_MODE_LAPTOP_MQ);
    appearanceViewModeMediaQuery.addEventListener('change', onAppearanceViewModeViewportChange);
}

function onAppearanceViewModeViewportChange() {
    if (getAppearanceViewMode() !== 'auto') return;
    applyAppearanceViewMode('auto');
}

function setAppearanceViewMode(mode) {
    const preference = normalizeAppearanceViewMode(mode);
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceViewMode = preference;
    saveData(appData);
    applyAppearanceViewMode(preference);
    setupAppearanceViewModeListener();
    applyAppearanceZoom(getActiveAppearanceZoom());
    if (typeof updateStatsCalendarLayoutForViewMode === 'function') {
        updateStatsCalendarLayoutForViewMode();
    }
}

function initAppearanceViewMode() {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceViewMode = getAppearanceViewMode();
    applyAppearanceViewMode(appData.settings.appearanceViewMode);
    setupAppearanceViewModeListener();
}

const APPEARANCE_ZOOM_PRESETS = Object.freeze([90, 100, 110, 125, 150]);
const APPEARANCE_ZOOM_MIN = 75;
const APPEARANCE_ZOOM_MAX = 200;
const APPEARANCE_ZOOM_STEP = 5;
const APPEARANCE_ZOOM_DEFAULT = 100;

function normalizeAppearanceZoom(value) {
    const n = typeof value === 'string' && value.endsWith('%')
        ? parseFloat(value)
        : parseFloat(value);
    if (!Number.isFinite(n)) return APPEARANCE_ZOOM_DEFAULT;
    const rounded = Math.round(n);
    return Math.min(APPEARANCE_ZOOM_MAX, Math.max(APPEARANCE_ZOOM_MIN, rounded));
}

function snapAppearanceZoom(value, step = APPEARANCE_ZOOM_STEP) {
    const n = normalizeAppearanceZoom(value);
    const snapped = Math.round(n / step) * step;
    return normalizeAppearanceZoom(snapped);
}

function getAppearanceZoom(data = appData) {
    return normalizeAppearanceZoom(data?.settings?.appearanceZoom);
}

function getPhoneViewZoom(data = appData) {
    const raw = data?.settings?.phoneViewZoom;
    return raw == null || raw === '' ? getAppearanceZoom(data) : normalizeAppearanceZoom(raw);
}

function getLaptopViewZoom(data = appData) {
    const raw = data?.settings?.laptopViewZoom;
    return raw == null || raw === '' ? getAppearanceZoom(data) : normalizeAppearanceZoom(raw);
}

function getActiveAppearanceZoom(data = appData) {
    const layout = resolveAppearanceViewLayout(getAppearanceViewMode(data));
    if (layout === 'laptop') return getLaptopViewZoom(data);
    return getPhoneViewZoom(data);
}

function isAppearanceZoomPreset(percent) {
    return APPEARANCE_ZOOM_PRESETS.includes(normalizeAppearanceZoom(percent));
}

function applyAppearanceZoom(percent = getActiveAppearanceZoom()) {
    const zoom = normalizeAppearanceZoom(percent);
    const scale = zoom / 100;
    const root = document.documentElement;
    if (root) {
        if (root.style?.setProperty) {
            root.style.setProperty('--app-zoom', String(scale));
            root.style.setProperty('--app-zoom-percent', `${zoom}`);
        }
        if (root.dataset) root.dataset.appZoom = String(zoom);
    }
    syncAppearanceZoomUI(zoom);
    updateAppearanceZoomLayoutMetrics();
    return zoom;
}

function updateAppearanceZoomLayoutMetrics() {
    const root = document.documentElement;
    const nav = document.querySelector('.bottom-nav');
    if (!root?.style?.setProperty) return;
    const zoom = normalizeAppearanceZoom(root.dataset?.appZoom || getActiveAppearanceZoom());
    const scale = zoom / 100;
    let navHeight = 110;
    if (nav) {
        const layoutHeight = nav.offsetHeight || 0;
        const visualHeight = nav.getBoundingClientRect?.().height || 0;
        if (layoutHeight > 0) navHeight = layoutHeight;
        else if (visualHeight > 0 && scale > 0) navHeight = visualHeight / scale;
    }
    root.style.setProperty(
        '--bottom-nav-clearance',
        `calc(${Math.ceil(navHeight)}px + env(safe-area-inset-bottom, 0px))`
    );
    root.style.setProperty('--tap-target-min', `calc(44px / var(--app-zoom))`);
}

function syncAppearanceZoomUI(percent = getActiveAppearanceZoom()) {
    const zoom = normalizeAppearanceZoom(percent);
    const isPreset = isAppearanceZoomPreset(zoom);
    const select = document.getElementById('appearance-zoom-preset');
    if (select) {
        select.value = isPreset ? String(zoom) : 'custom';
    }
    document.querySelectorAll('[data-appearance-zoom]').forEach((btn) => {
        const value = btn.getAttribute('data-appearance-zoom');
        const active = value === 'custom' ? !isPreset : String(zoom) === value;
        btn.classList.toggle('active', active);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
    const label = document.getElementById('appearance-zoom-value');
    if (label) label.textContent = `${zoom}%`;
    const slider = document.getElementById('appearance-zoom-slider');
    if (slider) {
        if (String(slider.value) !== String(zoom)) slider.value = String(zoom);
        slider.setAttribute('aria-valuenow', String(zoom));
    }
    const customInput = document.getElementById('appearance-zoom-custom');
    const customRow = document.getElementById('appearance-zoom-custom-row');
    if (customRow) customRow.classList.toggle('hidden', isPreset && select?.value !== 'custom');
    if (customInput && document.activeElement !== customInput) {
        customInput.value = String(zoom);
    }
    const live = document.getElementById('appearance-zoom-live');
    if (live) live.textContent = `App zoom ${zoom} percent`;
}

function persistAppearanceZoomSettings(zoom, data = appData) {
    if (!data.settings) data.settings = {};
    const z = normalizeAppearanceZoom(zoom);
    data.settings.appearanceZoom = z;
    const layout = resolveAppearanceViewLayout(getAppearanceViewMode(data));
    if (layout === 'laptop') data.settings.laptopViewZoom = z;
    else data.settings.phoneViewZoom = z;
    return z;
}

function setAppearanceZoom(percent, options = {}) {
    const zoom = normalizeAppearanceZoom(percent);
    persistAppearanceZoomSettings(zoom);
    if (options.persist !== false) saveData(appData);
    applyAppearanceZoom(zoom);
    return zoom;
}

function adjustAppearanceZoom(delta) {
    const current = getActiveAppearanceZoom();
    const next = snapAppearanceZoom(current + (parseFloat(delta) || 0));
    return setAppearanceZoom(next);
}

function stepAppearanceZoom(direction) {
    const dir = direction < 0 ? -1 : 1;
    return adjustAppearanceZoom(dir * APPEARANCE_ZOOM_STEP);
}

function onAppearanceZoomPresetChange(value) {
    if (value === 'custom') {
        document.getElementById('appearance-zoom-custom-row')?.classList.remove('hidden');
        document.getElementById('appearance-zoom-custom')?.focus();
        syncAppearanceZoomUI(getActiveAppearanceZoom());
        return;
    }
    setAppearanceZoom(value);
}

function onAppearanceZoomCustomInput(value) {
    const zoom = normalizeAppearanceZoom(value);
    setAppearanceZoom(zoom);
}

function resetAppearanceZoom() {
    return setAppearanceZoom(APPEARANCE_ZOOM_DEFAULT);
}

function normalizeAppearanceSpacing(value) {
    return value === 'compact' || value === 'comfortable' ? value : 'default';
}

function getAppearanceSpacing(data = appData) {
    return normalizeAppearanceSpacing(data?.settings?.appearanceSpacing);
}

function applyAppearanceSpacing(spacing = getAppearanceSpacing()) {
    const value = normalizeAppearanceSpacing(spacing);
    const scale = value === 'compact' ? 0.92 : (value === 'comfortable' ? 1.08 : 1);
    const root = document.documentElement;
    if (root) {
        if (root.style?.setProperty) root.style.setProperty('--app-spacing-scale', String(scale));
        if (root.dataset) root.dataset.appearanceSpacing = value;
    }
    const select = document.getElementById('appearance-spacing');
    if (select && select.value !== value) select.value = value;
    return value;
}

function setAppearanceSpacing(spacing) {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceSpacing = normalizeAppearanceSpacing(spacing);
    saveData(appData);
    applyAppearanceSpacing(appData.settings.appearanceSpacing);
}

function resetAppearanceSettings() {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceViewMode = 'auto';
    appData.settings.appearanceZoom = APPEARANCE_ZOOM_DEFAULT;
    appData.settings.phoneViewZoom = APPEARANCE_ZOOM_DEFAULT;
    appData.settings.laptopViewZoom = APPEARANCE_ZOOM_DEFAULT;
    appData.settings.appearanceSpacing = 'default';
    saveData(appData);
    applyAppearanceViewMode('auto');
    setupAppearanceViewModeListener();
    applyAppearanceZoom(APPEARANCE_ZOOM_DEFAULT);
    applyAppearanceSpacing('default');
    if (typeof updateStatsCalendarLayoutForViewMode === 'function') {
        updateStatsCalendarLayoutForViewMode();
    }
}

function initAppearanceZoom() {
    if (!appData.settings) appData.settings = {};
    appData.settings.appearanceZoom = getAppearanceZoom();
    if (appData.settings.phoneViewZoom == null) {
        appData.settings.phoneViewZoom = appData.settings.appearanceZoom;
    } else {
        appData.settings.phoneViewZoom = normalizeAppearanceZoom(appData.settings.phoneViewZoom);
    }
    if (appData.settings.laptopViewZoom == null) {
        appData.settings.laptopViewZoom = appData.settings.appearanceZoom;
    } else {
        appData.settings.laptopViewZoom = normalizeAppearanceZoom(appData.settings.laptopViewZoom);
    }
    appData.settings.appearanceSpacing = getAppearanceSpacing();
    applyAppearanceSpacing(appData.settings.appearanceSpacing);
    applyAppearanceZoom(getActiveAppearanceZoom());
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
        window.addEventListener('resize', updateAppearanceZoomLayoutMetrics, { passive: true });
    }
}

const SUBSTANCE_ICONS = ['🚬', '💨', '🍺', '🌿', '💊', '🍬', '💉', '🎯', '⚡', '🧪', '📦', '🔥', '❄️', '💧', '🌸', '🌀'];
const SUBSTANCE_COLORS = ['#4caf50', '#42a5f5', '#ffb74d', '#66bb6a', '#ab47bc', '#ef5350', '#78909c', '#26a69a', '#ff7043', '#5c6bc0'];

const CAFFEINE_SUBSTANCE_ID = 'caffeine';

const V1_NAME_TO_ID = {
    'Cigarettes': 'nicotine',
    'Vapes/Nicotine': 'nicotine',
    'Vape/Nicotine': 'nicotine',
    'Nicotine': 'nicotine',
    'Coke': 'coke',
    'Alcohol': 'alcohol',
    'Weed/THC': 'weed-thc',
    'LSD': 'lsd',
    'Molly': 'molly',
    'Xannax': 'xannax',
    'Ketamine': 'ketamine'
};

const SUBSTANCE_NAME_ALIASES = {
    'vapes/nicotine': 'nicotine',
    'vape nicotine': 'nicotine',
    'vape/nicotine': 'nicotine',
    'nicotine': 'nicotine',
    'cocaine': 'coke',
    'weed': 'weed/thc',
    'thc': 'weed/thc',
    'marijuana': 'weed/thc',
    'cigs': 'nicotine',
    'cigarette': 'nicotine',
    'cigarettes': 'nicotine',
    'xanax': 'xannax',
    'xannax': 'xannax',
    'mdma': 'molly',
    'ecstasy': 'molly',
    'acid': 'lsd',
    'alchocol': 'alcohol'
};

function normalizeSubstanceName(name) {
    if (name == null || name === '') return '';
    const normalized = String(name).trim().toLowerCase().replace(/\s+/g, ' ');
    return SUBSTANCE_NAME_ALIASES[normalized] || normalized;
}

const VAPE_NICOTINE_ID = 'vape-nicotine';
const LEGACY_CIGARETTES_ID = 'cigarettes';
const NICOTINE_ID = 'nicotine';

const NICOTINE_PRODUCT_TYPES = ['vape', 'cigarettes', 'pouches', 'gum', 'patches', 'other'];
const NICOTINE_PRODUCT_LABELS = {
    vape: 'Vape',
    cigarettes: 'Cigarettes',
    pouches: 'Nicotine pouches',
    gum: 'Nicotine gum',
    patches: 'Nicotine patches',
    other: 'Other'
};

function isNicotineSubstanceId(substanceId, data = appData) {
    if (!substanceId) return false;
    const id = normalizeSubstanceRef(substanceId, data);
    return id === NICOTINE_ID || id === VAPE_NICOTINE_ID || id === LEGACY_CIGARETTES_ID;
}

function isNicotineTrackingMode(substanceId, data = appData) {
    if (!substanceId) return false;
    if (isNicotineSubstanceId(substanceId, data)) return true;
    return getSubstanceTrackingMode(substanceId, data) === 'nicotine';
}

function inferNicotineProductTypeFromSubstanceId(substanceId, data = appData) {
    const id = normalizeSubstanceRef(substanceId, data);
    if (id === VAPE_NICOTINE_ID) return 'vape';
    if (id === LEGACY_CIGARETTES_ID) return 'cigarettes';
    const mode = getSubstanceTrackingMode(substanceId, data);
    if (mode === 'vape') return 'vape';
    if (mode === 'cigarettes') return 'cigarettes';
    return null;
}

function normalizeNicotineProductType(type) {
    return NICOTINE_PRODUCT_TYPES.includes(type) ? type : null;
}

function getNicotineProductType(record, data = appData) {
    if (!record) return null;
    const explicit = normalizeNicotineProductType(record.nicotineProductType);
    if (explicit) return explicit;
    if (record.cigarettesUsed != null || record.logMode === 'nicotine_cigarettes') return 'cigarettes';
    if (record.pouchesUsed != null || record.logMode === 'nicotine_pouches') return 'pouches';
    if (record.piecesUsed != null || record.logMode === 'nicotine_gum') return 'gum';
    if (record.patchesUsed != null || record.logMode === 'nicotine_patches') return 'patches';
    const unit = (record.unit || '').toLowerCase();
    if (unit === 'cigarettes' || unit === 'cigarette') return 'cigarettes';
    if (unit === 'pouches' || unit === 'pouch') return 'pouches';
    if (unit === 'pieces' || unit === 'piece') return 'gum';
    if (unit === 'patches' || unit === 'patch') return 'patches';
    if (isVapePuffUnit(record.unit) || record.logMode === 'vape_puffs' || record.logMode === 'percent_remaining') {
        return 'vape';
    }
    const substanceId = record.substanceId || record.substance
        || (record.unit != null ? getPurchaseSubstanceId(record) : getUseSubstanceId(record));
    return inferNicotineProductTypeFromSubstanceId(substanceId, data) || 'vape';
}

function normalizeNicotineSubstanceRef(substanceId, data = appData) {
    if (!substanceId) return '';
    const resolved = normalizeSubstanceRef(substanceId, data);
    return isNicotineSubstanceId(resolved, data) ? NICOTINE_ID : resolved;
}

function resolveNicotineFormProductType(substanceId) {
    if (!isNicotineTrackingMode(substanceId)) return null;
    const resolved = normalizeNicotineSubstanceRef(substanceId);
    const useSub = document.getElementById('use-substance')?.value;
    if (useSub && normalizeNicotineSubstanceRef(useSub) === resolved) {
        return getUseFormNicotineProductType();
    }
    const buySub = document.getElementById('buy-substance')?.value;
    if (buySub && normalizeNicotineSubstanceRef(buySub) === resolved) {
        return getBuyFormNicotineProductType();
    }
    const useTypeEl = document.getElementById('use-nicotine-product-type');
    if (useTypeEl && !document.getElementById('use-nicotine-product-type-group')?.classList.contains('hidden')) {
        return getUseFormNicotineProductType();
    }
    return null;
}

function isNicotineVapeFormContext(substanceId, payload = null) {
    if (!isNicotineTrackingMode(substanceId)) {
        return isVapeTrackingMode(substanceId);
    }
    const pt = payload?.nicotineProductType || resolveNicotineFormProductType(substanceId);
    if (pt) return pt === 'vape';
    return inferNicotineProductTypeFromSubstanceId(substanceId) === 'vape';
}

function isNicotineNonVapeFormContext(substanceId, payload = null) {
    if (!isNicotineTrackingMode(substanceId)) return false;
    const pt = payload?.nicotineProductType || resolveNicotineFormProductType(substanceId);
    return !!pt && pt !== 'vape' && pt !== 'other';
}

function getNicotineProductTypeLabel(type) {
    return NICOTINE_PRODUCT_LABELS[type] || type || 'Nicotine';
}

function getBuyFormNicotineProductType() {
    return normalizeNicotineProductType(document.getElementById('buy-nicotine-product-type')?.value) || 'vape';
}

function getUseFormNicotineProductType() {
    return normalizeNicotineProductType(document.getElementById('use-nicotine-product-type')?.value) || 'vape';
}

function isNicotineVapeProduct(record, data = appData) {
    if (!record) return false;
    return isNicotineTrackingMode(getPurchaseSubstanceId(record) || getUseSubstanceId(record), data)
        && getNicotineProductType(record, data) === 'vape';
}

function isNicotineCigarettesProduct(record, data = appData) {
    if (!record) return false;
    return isNicotineTrackingMode(getPurchaseSubstanceId(record) || getUseSubstanceId(record), data)
        && getNicotineProductType(record, data) === 'cigarettes';
}

function isNicotinePurchase(purchase, data = appData) {
    return isNicotineTrackingMode(getPurchaseSubstanceId(purchase), data);
}

