    setupEventListeners();
    ensureAppDataSubstancesReady(appData);
    ensureDashboardSubstanceDropdownReady();
    selectedSubstanceId = resolveDefaultSelectedSubstanceId() || DASHBOARD_ALL;
    ensureSelectedSubstanceIdValid();
    syncUseLogFormFromSelectedSubstance();
    syncBuyFormFromSelectedSubstance();
    updateDashboard();
    renderRecentUseList();
    refreshTaperDashboard();
    renderSubstancesList();
    renderStoresList();
    setupBuyTrackerForm();
    loadInventoryFiltersPanelState();
    updateInventoryFiltersPanelUI();
    setupUseLogForm();
    setupSubstanceForm();
    setupStatsDateRange();
    setDefaultUseLogDateTime();
    refreshAllRecoveryStreaks();
    updateQuickActions();
    updateDashboardMainDisplay();
    applyMainSubstanceToForms();

    updateLastSavedDisplay();
    applyCollapsedSections();
