function exportJsonBackup() {
    const appDataExport = cleanExportData(appData);
    const exportObject = {
        app: 'recovery-tracker',
        version: 2,
        exportedAt: new Date().toISOString(),
        appData: appDataExport
    };
    const dataStr = JSON.stringify(exportObject, null, 2);
    JSON.parse(dataStr);
    const blob = new Blob([dataStr], { type: 'application/json' });
    downloadBlob(blob, `recovery-tracker-backup-${getLocalDateString()}.json`);
}

function exportData() {
    exportJsonBackup();
}

function csvEscape(value) {
    const s = String(value ?? '');
    if (/[",\n\r]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
    return s;
}

function buildUseHistoryCsvRows(options = {}) {
    const substanceId = options.substanceId !== undefined
        ? options.substanceId
        : getUseLogViewSubstanceId();
    const rows = buildUseHistoryRows(substanceId);
    const family = getUseHistoryColumnFamily(substanceId);
    const columns = getUseHistoryVisibleColumns(substanceId).filter(id => id !== 'select' && id !== 'actions');
    const headers = columns.map(colId => getUseHistoryColumnLabel(colId, substanceId));
    const body = rows.map(({ entry, sub }) => columns.map(colId => {
        switch (colId) {
            case 'date': return entry.date || '';
            case 'start': return entry.startTime || entry.time || '';
            case 'end': return entry.endTime || '';
            case 'duration': return formatDurationHours(entry.durationHours) || '';
            case 'substance': return sub?.name || getSubstanceName(getUseSubstanceId(entry)) || '';
            case 'productType': return getNicotineProductTypeLabel(getNicotineProductType(entry));
            case 'transactionType': return formatUseHistoryTransactionType(entry);
            case 'amount': {
                if (isVapeUseLog(entry) || getNicotineProductType(entry) === 'vape') {
                    return String(formatUseHistoryVapeAmountHtml(entry)).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
                }
                return String(formatUseHistoryAmountHtml(entry)).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            }
            case 'unit': return entry.unit || '';
            case 'tabs': return entry.tabsUsed ?? '';
            case 'ug': return entry.ugUsed ?? '';
            case 'pills': return entry.pillsUsed ?? '';
            case 'mg': return entry.mgUsed ?? '';
            case 'strength': {
                const strength = entry.strengthPerPillAtTimeOfUse ?? entry.mgPerPillAtTimeOfUse;
                return strength != null ? `${strength} ${entry.strengthUnitAtTimeOfUse || 'mg'}` : '';
            }
            case 'cost': return entry.estimatedCost ?? '';
            case 'gPerHour': return formatUseHistoryGramsPerHour(entry);
            case 'sharedAmount':
                return isSharedUseLog(entry)
                    ? `Me ${getLogPersonalAmount(entry)} · ${entry.sharedWithName || 'Other'} ${getLogSharedAmount(entry)}`
                    : '';
            case 'multiDayRange': {
                if (!isAlcoholMultiDayParentLog(entry)) return '';
                const start = entry.startDate || entry.distributedStartDate || entry.date;
                const end = entry.endDate || entry.distributedEndDate || entry.date;
                return `${start} – ${end}`;
            }
            case 'dailyBreakdown':
                return isAlcoholMultiDayParentLog(entry)
                    ? formatAlcoholMultiDayBreakdownLines(entry).join(' | ')
                    : '';
            case 'count': return entry.count ?? '';
            case 'rate': return entry.useRate != null ? entry.useRate : '';
            case 'inventory':
            case 'supply':
                return String(formatInventoryLinkDisplay(entry)).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            case 'notes': return entry.notes || '';
            default: return '';
        }
    }));
    return { headers, body, family, rows, substanceId };
}

function exportUseHistoryCsv(options = {}) {
    const { headers, body } = buildUseHistoryCsvRows(options);
    const lines = [headers.map(csvEscape).join(',')];
    body.forEach(row => lines.push(row.map(v => csvEscape(v)).join(',')));
    const blob = new Blob([lines.join('\n')], { type: 'text/csv;charset=utf-8' });
    downloadBlob(blob, `use-history-${getLocalDateString()}.csv`);
}

function exportDataCsv() {
    const rows = [];
    rows.push(['Record Type', 'Substance', 'Date', 'Start', 'End', 'Amount', 'Unit', 'Transaction Type', 'Product Type', 'Tabs Used', 'Ug Used', 'Pills Used', 'Mg Used', 'Count', 'Notes'].map(csvEscape).join(','));
    const filteredLogs = getFilteredUseLogsForView();
    filteredLogs.forEach(log => {
        rows.push([
            log.type === 'session' ? 'Use Session' : 'Use Quick',
            getSubstanceName(log.substanceId),
            log.date,
            log.startTime || log.time || '',
            log.endTime || '',
            log.amount,
            log.unit,
            getLogTransactionType(log),
            isNicotineSubstanceId(getUseSubstanceId(log)) ? (getNicotineProductType(log) || '') : '',
            log.tabsUsed ?? '',
            log.ugUsed ?? '',
            log.pillsUsed ?? '',
            log.mgUsed ?? '',
            log.count ?? '',
            log.notes || ''
        ].map(csvEscape).join(','));
    });
    rows.push('');
    rows.push(['Record Type', 'Substance', 'Date', 'Time', 'Quantity', 'Unit', 'Pill Qty', 'Strength/Pill', 'Strength Unit', 'Total Mg', 'Total Cost', 'How Acquired', 'Gift From', 'Store', 'Flavor', 'Notes'].map(csvEscape).join(','));
    (appData.purchases || []).forEach(p => {
        rows.push([
            'Purchase',
            getSubstanceName(p.substanceId),
            p.date,
            p.time || '',
            p.quantity,
            p.unit,
            p.pillQuantity ?? '',
            p.strengthPerPill ?? '',
            p.strengthUnit ?? '',
            p.totalMg ?? '',
            p.totalCost ?? '',
            getPurchaseAcquisitionType(p),
            getPurchaseGiftSource(p),
            p.store || '',
            purchaseSupportsFlavor(p) ? getVapePurchaseFlavor(p) : '',
            p.notes || ''
        ].map(csvEscape).join(','));
    });
    const blob = new Blob([rows.join('\n')], { type: 'text/csv;charset=utf-8' });
    downloadBlob(blob, `recovery-tracker-export-${getLocalDateString()}.csv`);
}

function stripJsonBom(text) {
    if (typeof text !== 'string') return '';
    return text.replace(/^\uFEFF/, '').trim();
}

function isRecognizableBackupPayload(parsed) {
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return false;
    if (parsed.app === 'recovery-tracker') return true;
    if (parsed.appData && typeof parsed.appData === 'object' && !Array.isArray(parsed.appData)) return true;
    if (parsed.data && typeof parsed.data === 'object' && !Array.isArray(parsed.data)) return true;
    return (
        'substances' in parsed ||
        'logs' in parsed ||
        'useLogs' in parsed ||
        'purchases' in parsed ||
        'settings' in parsed ||
        'taperPlans' in parsed ||
        'taperPlansV2' in parsed
    );
}

function extractAppDataFromBackup(parsed) {
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
    if (parsed.appData && typeof parsed.appData === 'object' && !Array.isArray(parsed.appData)) {
        return parsed.appData;
    }
    if (parsed.data && typeof parsed.data === 'object' && !Array.isArray(parsed.data)) {
        return parsed.data;
    }
    if (isRecognizableBackupPayload(parsed)) {
        return parsed;
    }
    return null;
}

function normalizeImportedAppData(raw) {
    const data = raw && typeof raw === 'object' && !Array.isArray(raw)
        ? JSON.parse(JSON.stringify(raw))
        : {};

    if (!Array.isArray(data.logs) && Array.isArray(data.useLogs)) {
        data.logs = data.useLogs;
    }
    if (!Array.isArray(data.logs)) data.logs = [];
    if (!Array.isArray(data.purchases)) data.purchases = [];
    if (!Array.isArray(data.cravings)) data.cravings = [];
    if (!Array.isArray(data.substances)) data.substances = [];
    ensureAppDataSubstancesReady(data);
    if (!data.settings || typeof data.settings !== 'object' || Array.isArray(data.settings)) {
        data.settings = JSON.parse(JSON.stringify(defaultData.settings));
    }
    if (!data.taperPlans || typeof data.taperPlans !== 'object' || Array.isArray(data.taperPlans)) {
        data.taperPlans = {};
    }
    if (!Array.isArray(data.taperPlansV2)) data.taperPlansV2 = [];
    if (!data.recoveryStreaks || typeof data.recoveryStreaks !== 'object' || Array.isArray(data.recoveryStreaks)) {
        data.recoveryStreaks = {};
    }
    if (!data.privacy || typeof data.privacy !== 'object' || Array.isArray(data.privacy)) {
        data.privacy = JSON.parse(JSON.stringify(defaultData.privacy));
    }
    if (!data.migrations || typeof data.migrations !== 'object' || Array.isArray(data.migrations)) {
        data.migrations = {};
    }

    delete data.useLogs;
    delete data.version;
    delete data.exportedAt;
    delete data.app;
    delete data.savedAt;
    delete data.reason;
    return data;
}

function validateBackupData(data) {
    if (!data || typeof data !== 'object' || Array.isArray(data)) {
        return {
            ok: false,
            message: 'This JSON opened, but it does not look like a Recovery Tracker backup.'
        };
    }
    return { ok: true, data: normalizeImportedAppData(data) };
}

function repairAppDataAfterImport(data) {
    repairVapeInventoryLinks(data);
    repairDataConsistency(data);
}

function mergeArrayById(existing, incoming) {
    const map = new Map((existing || []).map(item => [item.id, item]));
    (incoming || []).forEach(item => {
        if (item?.id != null) map.set(item.id, item);
        else map.set(`import-${Date.now()}-${Math.random()}`, item);
    });
    return [...map.values()];
}

function mergeImportedData(current, imported) {
    const merged = JSON.parse(JSON.stringify(current));
    if (Array.isArray(imported.useLogs)) {
        imported.logs = mergeArrayById(imported.logs || [], imported.useLogs);
        delete imported.useLogs;
    }
    merged.substances = mergeArrayById(merged.substances, imported.substances);
    merged.logs = mergeArrayById(merged.logs, imported.logs);
    merged.purchases = mergeArrayById(merged.purchases, imported.purchases);
    merged.cravings = mergeArrayById(merged.cravings || [], imported.cravings || []);
    merged.settings = {
        ...merged.settings,
        ...imported.settings,
        substanceSettings: {
            ...(merged.settings?.substanceSettings || {}),
            ...(imported.settings?.substanceSettings || {})
        }
    };
    merged.taperPlans = { ...(merged.taperPlans || {}), ...(imported.taperPlans || {}) };
    if (Array.isArray(imported.taperPlansV2)) {
        merged.taperPlansV2 = mergeArrayById(merged.taperPlansV2 || [], imported.taperPlansV2);
    }
    merged.recoveryStreaks = { ...(merged.recoveryStreaks || {}), ...(imported.recoveryStreaks || {}) };
    if (imported.privacy && typeof imported.privacy === 'object') {
        merged.privacy = { ...merged.privacy, ...imported.privacy };
    }
    ensureAppDataSubstancesReady(merged);
    return merged;
}

function buildImportPreview(imported, current = appData) {
    const incomingLogs = imported.logs || [];
    const incomingPurchases = imported.purchases || [];
    const incomingSubs = imported.substances || [];
    const currentLogIds = new Set((current.logs || []).map(l => String(l.id)));
    const currentPurchaseIds = new Set((current.purchases || []).map(p => String(p.id)));
    const currentSubIds = new Set((current.substances || []).map(s => String(s.id)));

    const newLogs = incomingLogs.filter(l => !currentLogIds.has(String(l.id)));
    const updatedLogs = incomingLogs.filter(l => currentLogIds.has(String(l.id)));
    const newPurchases = incomingPurchases.filter(p => !currentPurchaseIds.has(String(p.id)));
    const updatedPurchases = incomingPurchases.filter(p => currentPurchaseIds.has(String(p.id)));
    const newSubs = incomingSubs.filter(s => !currentSubIds.has(String(s.id)));
    const updatedSubs = incomingSubs.filter(s => currentSubIds.has(String(s.id)));

    return {
        summary: {
            substances: incomingSubs.length,
            logs: incomingLogs.length,
            purchases: incomingPurchases.length,
            newLogs: newLogs.length,
            updatedLogs: updatedLogs.length,
            newPurchases: newPurchases.length,
            updatedPurchases: updatedPurchases.length,
            newSubstances: newSubs.length,
            updatedSubstances: updatedSubs.length
        },
        conflicts: [
            ...updatedLogs.slice(0, 8).map(l => ({ type: 'log', id: l.id, label: `Log ${l.id} will be updated on merge` })),
            ...updatedPurchases.slice(0, 8).map(p => ({ type: 'purchase', id: p.id, label: `Purchase ${p.id} will be updated on merge` })),
            ...updatedSubs.slice(0, 5).map(s => ({ type: 'substance', id: s.id, label: `Substance ${s.name || s.id} already exists` }))
        ]
    };
}

let pendingImportData = null;

function openImportPreviewModal(imported) {
    pendingImportData = imported;
    const preview = buildImportPreview(imported);
    const summaryEl = document.getElementById('import-preview-summary');
    const conflictsEl = document.getElementById('import-preview-conflicts');
    if (summaryEl) {
        const s = preview.summary;
        summaryEl.innerHTML = `
            <div class="taper-mini-stats">
                <div class="taper-mini-stat"><span>Substances</span><strong>${s.substances}</strong></div>
                <div class="taper-mini-stat"><span>Use logs</span><strong>${s.logs}</strong></div>
                <div class="taper-mini-stat"><span>Purchases</span><strong>${s.purchases}</strong></div>
                <div class="taper-mini-stat"><span>New logs</span><strong>${s.newLogs}</strong></div>
                <div class="taper-mini-stat"><span>Updated logs (merge)</span><strong>${s.updatedLogs}</strong></div>
                <div class="taper-mini-stat"><span>New purchases</span><strong>${s.newPurchases}</strong></div>
                <div class="taper-mini-stat"><span>Updated purchases (merge)</span><strong>${s.updatedPurchases}</strong></div>
            </div>`;
    }
    if (conflictsEl) {
        conflictsEl.innerHTML = preview.conflicts.length
            ? `<h4>Conflicts / updates</h4><ul>${preview.conflicts.map(c => `<li>${escapeHtml(c.label)}</li>`).join('')}</ul>`
            : '<p class="field-hint">No ID conflicts with current data.</p>';
    }
    document.getElementById('import-preview-modal')?.classList.remove('hidden');
}

function closeImportPreviewModal() {
    pendingImportData = null;
    document.getElementById('import-preview-modal')?.classList.add('hidden');
}

function confirmImportPreview(mode) {
    if (!pendingImportData) return;
    const imported = pendingImportData;
    closeImportPreviewModal();
    pushChangeHistory(`before-import-${mode}`, { summary: `Before ${mode} import` });
    applyImportedBackup(imported, mode);
    alert(mode === 'merge' ? 'Backup merged successfully.' : 'Backup replaced current data.');
    renderChangeHistoryPanel();
}

function applyImportedBackup(imported, mode) {
    createAutoBackup(mode === 'replace' ? 'before-import-replace' : 'before-import-merge');
    const normalized = normalizeImportedAppData(imported);
    if (mode === 'replace') {
        appData = normalized;
    } else {
        appData = mergeImportedData(appData, normalized);
    }
    normalizeAppData(appData);
    repairAppDataAfterImport(appData);
    saveData(appData);
    refreshAppAfterDataChange();
}

async function handleImportJsonFile(event) {
    const input = event.target;
    const file = input.files?.[0];
    if (!file) return;

    try {
        const raw = stripJsonBom(await file.text());
        if (!raw) {
            alert('The selected file is empty.');
            return;
        }

        let parsed;
        try {
            parsed = JSON.parse(raw);
        } catch (parseErr) {
            console.error('Import JSON parse failed:', parseErr);
            alert('This file is not valid JSON. Export a fresh JSON backup from Recovery Tracker and try again.');
            return;
        }

        if (!isRecognizableBackupPayload(parsed)) {
            alert('This JSON opened, but it does not look like a Recovery Tracker backup.');
            return;
        }

        const extracted = extractAppDataFromBackup(parsed);
        if (!extracted) {
            alert('This JSON opened, but it does not look like a Recovery Tracker backup.');
            return;
        }

        const validation = validateBackupData(extracted);
        if (!validation.ok) {
            alert(validation.message || 'This JSON opened, but it does not look like a Recovery Tracker backup.');
            return;
        }

        openImportPreviewModal(validation.data);
    } catch (err) {
        console.error('Import failed:', err);
        alert('Import failed. Check the console for details.');
    } finally {
        input.value = '';
    }
}

function triggerImportJsonBackup() {
    document.getElementById('import-json-input')?.click();
}

function clearAllData() {
    if (!confirm('Clear ALL data? This cannot be undone.')) return;
    if (!confirm('Delete all logs, substances, and settings?')) return;
    pushChangeHistory('before-clear', { summary: 'Before clearing all data' });
    createAutoBackup('before-clear');
    appData = getDefaultAppData();
    appData.substances = getDefaultSubstances();
    saveData(appData);
    refreshAppAfterDataChange();
    alert('All data cleared.');
}

